window.__finlexDocLoaded(10218,{"id":10218,"articles":[{"id":1000919,"no":"Overview","heading":"Scope & Core Objective (Public Summary)","text":"Requires all research and development (R&D) costs to be expensed as incurred (with narrow exceptions for software development under ASC 350-40 / ASC 985-20 and IPR&D acquired in a business combination under ASC 805).","seq":0},{"id":1000920,"no":"ASC 730-10","heading":"Immediate Expensing of R&D Costs","text":"• General Rule (ASC 730-10-25-1): ALL internal research AND development costs are expensed as incurred — no capitalization of development phase costs.\n• Narrow Exceptions: (1) Internal-use software (ASC 350-40) and external-sale software post-technological feasibility (ASC 985-20); (2) Assets with alternative future uses (depreciated to R&D); (3) In-process R&D (IPR&D) acquired in a business combination (capitalized as indefinite-lived intangible under ASC 805 / ASC 350).","seq":1},{"id":1000921,"no":"US GAAP vs. IFRS / CAS","heading":"Key Cross-Framework Differences","text":"• Iconic Divergence from IAS 38 / CAS 6: IAS 38.57 and CAS 6 REQUIRE capitalization of internal development costs once 6 technical/commercial feasibility criteria are met; ASC 730 EXPENSES virtually all internal R&D as incurred (except software), significantly impacting EBITDA and R&D-heavy tech/pharma comparisons.","seq":2},{"id":1000922,"no":"Official Access","heading":"Official FASB Codification & Reference Entry","text":"Official Portal (FASB Accounting Standards Codification®): https://asc.fasb.org/\nStatus: in_force (FASB ASC free Basic View available at https://asc.fasb.org/).","seq":3}]});
